  "rewrite_sql": "-- Set timeouts to fail fast instead of queuing behind traffic
SET lock_timeout = '2s';
SET statement_timeout = '5s';

-- Add column without default (metadata-only, no rewrite)
ALTER TABLE order_items ADD COLUMN token double precision;

-- Set default for future inserts (metadata-only)
ALTER TABLE order_items ALTER COLUMN token SET DEFAULT random();

-- Backfill existing rows in batches
-- Temporarily increase statement_timeout for the backfill loop
SET statement_timeout = '5min';

DO $$
DECLARE
  batch_size int := 1000;
  rows_updated int;
BEGIN
  LOOP
    UPDATE order_items
    SET token = random()
    WHERE id IN (
      SELECT id
      FROM order_items
      WHERE token IS NULL
      LIMIT batch_size
    );

    GET DIAGNOSTICS rows_updated = ROW_COUNT;
    EXIT WHEN rows_updated = 0;

    -- Brief pause between batches to reduce lock contention
    PERFORM pg_sleep(0.01);
  END LOOP;
END $$;",
  "notes": "Replaced single ALTER TABLE with volatile DEFAULT (which causes full table rewrite) with three-step safe approach: (1) ADD COLUMN without default (metadata-only), (2) SET DEFAULT for future rows (metadata-only), (3) backfill existing rows in batches. Added lock_timeout/statement_timeout guards. Batched backfill avoids long-running transactions and ACCESS EXCLUSIVE lock on the entire table. Same end state: all existing rows have random() values, future inserts get random() default.",
